  "Routing": "  sealed interface Uncertain<out T> {\n    data class Known<T>(val value: T) : Uncertain<T>\n    data class Unknown(val reason: String) : Uncertain<Nothing>\n  }\n\n  fun <T> known(value: T): Uncertain<T> = Uncertain.Known(value)\n  fun unknown(reason: String): Uncertain<Nothing> = Uncertain.Unknown(reason)\n\n  inline fun <T> Uncertain<T>.orElse(fallback: () -> T): T = when (this) {\n    is Uncertain.Known -> value\n    is Uncertain.Unknown -> fallback()\n  }\n\n  data class ClassifiedIntent(val inferred: Uncertain<String>)\n\n  enum class Route { EnterWorld, PendingWorld, OpenUrl, ShowResult, Deny }\n\n  fun resolveIntent(intent: ClassifiedIntent): String {\n    return (intent.inferred).orElse { \"deny\" }\n  }\n\n  fun admissiblePayload(nonEmpty: Boolean, withinLimit: Boolean, controlsSafe: Boolean, syntaxSafe: Boolean): Boolean {\n    if (nonEmpty) {\n      if (withinLimit) {\n        if (controlsSafe) {\n          if (syntaxSafe) {\n            return true\n          } else {\n            return false\n          }\n        } else {\n          return false\n        }\n      } else {\n        return false\n      }\n    } else {\n      return false\n    }\n  }\n\n  fun decideRoute(intent: String, autoImmerse: Boolean): Route {\n    if (intent == \"world\") {\n      if (autoImmerse) {\n        return Route.EnterWorld\n      } else {\n        return Route.PendingWorld\n      }\n    } else {\n      if (intent == \"open\") {\n        return Route.OpenUrl\n      } else {\n        if (intent == \"copy\") {\n          return Route.ShowResult\n        } else {\n          return Route.Deny\n        }\n      }\n    }\n  }",
